import type { IAuth, INotification } from "@benchmark/erp-api";
import { NestiaSimulator, PlainFetcher, type IConnection } from "@nestia/fetcher";
import typia, { type Primitive, Resolved } from "typia";

/**
 * Dispatches a queued notification exactly once.
 *
 * @evidence docs/analysis/03-functional-requirements.md#req-fun-notification-003-dispatches-queued-notifications Dispatches queued notifications.
 *
 * @controller NotificationDispatchController.dispatch
 * @path POST /notification-dispatch/:id
 * @accessor api.functional.notification_dispatch.dispatch
 * @nestia Generated by Nestia - https://github.com/samchon/nestia
 */
export async function dispatch(
  connection: IConnection<dispatch.Headers>,
  id: string,
): Promise<dispatch.Output> {
  return true === connection.simulate
    ? dispatch.simulate(connection, id)
    : PlainFetcher.fetch(connection, {
        ...dispatch.METADATA,
        template: dispatch.METADATA.path,
        path: dispatch.path(id),
      });
}
export namespace dispatch {
  export type Headers = Resolved<IAuth.IHeaders>;
  export type Output = Primitive<INotification>;

  export const METADATA = {
    method: "POST",
    path: "/notification-dispatch/:id",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
    status: 201,
  } as const;

  export const path = (id: string) =>
    `/notification-dispatch/${encodeURIComponent(id?.toString() ?? "null")}`;
  export const random = (): Resolved<Primitive<INotification>> =>
    typia.random<Primitive<INotification>>();
  export const simulate = (
    connection: IConnection<dispatch.Headers>,
    id: string,
  ): Output => {
    const assert = NestiaSimulator.assert({
      method: METADATA.method,
      host: connection.host,
      path: path(id),
      contentType: "application/json",
    });
    assert.param("id")(() => typia.assert(id));
    return random();
  };
}
